#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "kebab-case")]
pub enum Stage {
    SeatOpen,
    SourceRegistration,
    UdevMonitor,
    InputSetup,
    InputResume,
    DeviceOpen,
    DeviceClose,
    SeatControl,
    DeviceMismatch,
    DeviceFlags,
    DeviceDuplicate,
    DrmInitialize,
    GbmInitialize,
    EglInitialize,
    RendererInitialize,
    DrmResources,
    DrmEvent,
    Lifecycle,
    Inactive,
